export const sendFriendRequest = catchAsync(async (req, res) => {
  try{
     // send friend request logic here
    const { frindsId } = req.body.userRequest[0];
    let msg = "";
    let currentUser = await UserModel.findOne({ _id: frindsId }, { requestReceived: 1, _id: 1 });
    if (frindsId !== undefined) {
      const index = currentUser.requestReceived.findIndex((item) => item === frindsId);
      if (index === -1) {
        currentUser.requestReceived = [...currentUser.requestReceived, frindsId];
        msg = "sent";
      } else {
        msg = "Already sent";
      }

      await currentUser.save();
    }
    return res.status(201).send({ msg: msg, currentUser });
  }
  catch(err){}
 
});

